<div class="text-end mb-3"><a class="btn btn-primary" href="<?= e(base_url('admin/category/add')) ?>">+ Thêm danh mục</a></div><div class="table-responsive"><table class="table table-bordered bg-white"><thead><tr><th>ID</th><th>Tên</th><th>Slug</th><th>Số sản phẩm</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($categories as $c): ?><tr><td><?= (int)$c['id'] ?></td><td><?= e($c['name']) ?></td><td><?= e($c['slug']) ?></td><td><?= (int)$c['product_count'] ?></td><td><?= e($c['status']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= e(base_url('admin/category/edit/'.$c['id'])) ?>">Sửa</a> <form class="d-inline" method="post" action="<?= e(base_url('admin/category/delete')) ?>" onsubmit="return confirm('Xóa danh mục?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="btn btn-sm btn-outline-danger" <?= $c['product_count']?'disabled':'' ?>>Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></div>
